endpoint.curlExample:
curl --location --request PUT 'https://api.onlinesales.ai/marketing/v1/advertiser/<advertiser_id>/sponsored_products/campaigns/<campaign_id>/keyword_settings/negative' \
--header 'x-token: <ADD YOUR AUTH TOKEN HERE>' \
--header 'x-retailer-id: <ADD RETAILER-ID HERE>' \
--header 'Content-Type: application/json' \
--data '{
    "keywords": [
        {
            "keyword": "<add your keyword here>",
            "match_type": "PHRASE",
            "status": "ACTIVE",
            "bid_value": 2
        }
    ]
}'
